new:
this.changeChieftain <- function (){
	local character = this.getChieftain();
	if (character == null)
	{
		return;
	}
	character.m.Name = ::NorthMod.Utils.barbarianNameOnly();
	character.setTitle(::NorthMod.Utils.barbarianTitle());
	character.assignRandomEquipment();
}
